insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_16_v1'
from (values
('127.100.d.1.A',3,'A jobsite with a safety culture is one where workers:','["Look out for their own and each other''s safety every day", "Ignore hazards", "Only follow rules when watched", "Leave safety to inspectors"]'::jsonb,0,'Safety culture means shared daily commitment.','original'),
('127.100.d.1.A',4,'A foreman stops work to fix an unguarded edge before continuing. This builds a:','["Cost-cutting rule", "Safety culture", "Schedule myth", "Production delay culture"]'::jsonb,1,'Leaders model safe priorities.','original'),
('127.100.d.1.B',3,'A strong safety culture is important in the crafts because it:','["Hides near misses", "Raises accident rates", "Reduces injuries and lost time", "Removes training"]'::jsonb,2,'Safe sites protect people and projects.','original'),
('127.100.d.1.B',4,'Workers who report near misses without fear of blame help to:','["Create more hazards", "Hide problems", "Delay all projects", "Prevent future injuries"]'::jsonb,3,'Open reporting finds hazards early.','original'),
('127.100.d.1.C',3,'OSHA stands for the:','["Occupational Safety and Health Administration", "Outdoor Safety Home Association", "Official Site Housing Authority", "Open Shop Hazard Agency"]'::jsonb,0,'OSHA sets and enforces workplace safety rules.','original'),
('127.100.d.1.C',4,'An OSHA inspector may visit a construction site to:','["Sell tools", "Check compliance with safety standards", "Set material prices", "Hire workers"]'::jsonb,1,'OSHA enforces standards.','original'),
('127.100.d.1.D',3,'A ladder used to reach an upper level should extend above the landing by:','["Ten feet", "One inch", "About 3 feet", "Zero inches"]'::jsonb,2,'Extension gives a handhold for stepping off.','original'),
('127.100.d.1.D',4,'Scaffold platforms over a certain height must have:','["Loose planks", "No protection", "Only tape", "Guardrails or personal fall arrest"]'::jsonb,3,'Edge protection prevents falls.','original'),
('127.100.d.1.E',3,'Hazard communication (HazCom) requires employers to:','["Label chemicals and train workers on their hazards", "Skip training", "Remove all labels", "Hide chemical information"]'::jsonb,0,'Workers have the right to know.','original'),
('127.100.d.1.E',4,'A container of stain with a missing label should be:','["Poured out", "Reported and not used until identified", "Used anyway", "Mixed with others"]'::jsonb,1,'Unlabeled chemicals are unsafe.','original'),
('127.100.d.1.F',3,'A Safety Data Sheet (SDS) for a glue tells workers about:','["Its delivery date", "Its color", "Its hazards, handling, and first aid", "Its price"]'::jsonb,2,'SDS lists safety information.','original'),
('127.100.d.1.F',4,'Section 4 of an SDS typically covers:','["Store locations", "Shipping rates", "Product slogan", "First-aid measures"]'::jsonb,3,'First-aid steps are given in a set section.','original'),
('127.100.d.1.G',3,'OSHA''s General Duty Clause requires employers to provide a workplace free from:','["Recognized serious hazards", "Deadlines", "Customers", "Paperwork"]'::jsonb,0,'Employers must protect workers from known hazards.','original'),
('127.100.d.1.G',4,'The General Duty Clause applies even when:','["The site is empty", "No specific OSHA standard covers the hazard", "The job is done", "Every standard exists"]'::jsonb,1,'It fills gaps in specific standards.','original'),
('127.100.d.1.H',3,'OSHA 1926 is the set of safety standards for:','["Farming", "Shipping", "Construction", "Schools"]'::jsonb,2,'Part 1926 governs construction.','original'),
('127.100.d.1.H',4,'Subpart C of 1926 covers general safety and health provisions, including the employer''s duty to:','["Choose paint colors", "Collect taxes", "Set prices", "Provide training and safe tools"]'::jsonb,3,'Subpart C sets basic duties.','original'),
('127.100.d.1.I',3,'Most jobsite accidents are caused by unsafe acts and:','["Unsafe conditions", "Good weather", "Safe tools", "Clear plans"]'::jsonb,0,'Both acts and conditions lead to accidents.','original'),
('127.100.d.1.I',4,'Rushing a cut by removing a saw guard is an example of an:','["Unsafe condition", "Unsafe act", "Safe habit", "Required step"]'::jsonb,1,'The worker''s choice created the hazard.','original'),
('127.100.d.1.J',3,'Direct accident costs include medical bills and:','["Extra profit", "Lunch savings", "Workers'' compensation", "Free equipment"]'::jsonb,2,'Direct costs are insured expenses.','original'),
('127.100.d.1.J',4,'Indirect accident costs include:','["Insurance premiums only", "Only hospital bills", "Only fines", "Lost production and replacement training"]'::jsonb,3,'Indirect costs often exceed direct ones.','original'),
('127.100.d.1.K',4,'Hard hats help to protect against:','["Struck-by head injuries", "Hearing loss", "Heat only", "Chemical burns"]'::jsonb,0,'Hard hats absorb impact.','original'),
('127.100.d.1.L',3,'A caught-in-between hazard includes:','["A paper cut", "Being crushed by equipment or a trench cave-in", "A sneeze", "A sunburn"]'::jsonb,1,'Caught-in hazards compress the body.','original'),
('127.100.d.1.L',4,'Trenches deeper than five feet require:','["No protection", "Extra tools", "Protective systems such as shoring", "Only warning tape"]'::jsonb,2,'Trench walls can collapse.','original'),
('127.100.d.1.M',3,'Other construction hazards on a site include asbestos, lead, and:','["Daylight", "Birdsong", "Fresh air", "Silica dust"]'::jsonb,3,'Dusts and toxic materials are hazards.','original'),
('127.100.d.1.M',4,'Disturbing old paint in older buildings may release:','["Lead dust", "Pollen", "Carbon dioxide only", "Helium"]'::jsonb,0,'Lead paint is a known hazard.','original'),
('127.100.d.1.N',3,'A safe work practice around electrical hazards is to:','["Use wet cords", "Stay clear of overhead power lines", "Bypass breakers", "Touch live wires"]'::jsonb,1,'Distance prevents contact.','original'),
('127.100.d.1.N',4,'Before working on a circuit, a worker should use:','["Extra lights", "Wet gloves", "Lockout and tagout", "A damp ladder"]'::jsonb,2,'Lockout keeps power off.','original'),
('127.100.d.1.O',3,'Hazard recognition means:','["Waiting for injuries", "Hiding hazards", "Ignoring dangers", "Spotting dangers before they cause harm"]'::jsonb,3,'Identify early to prevent harm.','original'),
('127.100.d.1.O',4,'A walkthrough of the site each morning is a way to:','["Find new hazards before work starts", "Avoid reporting", "Slow down progress", "Avoid planning"]'::jsonb,0,'Daily checks catch changes.','original'),
('127.100.d.1.P',3,'Risk assessment compares the likelihood of harm with its:','["Brand", "Severity", "Cost of lunch", "Color"]'::jsonb,1,'Risk equals likelihood and severity.','original'),
('127.100.d.1.P',4,'A task that is likely to occur and could cause serious injury is a:','["No-risk task", "Approved shortcut", "High-risk task", "Low-risk task"]'::jsonb,2,'High likelihood and severity mean high risk.','original'),
('127.100.d.1.Q',3,'Personal protective equipment should be:','["Shared dirty", "Stored wet", "Worn damaged", "Inspected before use and kept clean"]'::jsonb,3,'PPE must be in good condition.','original'),
('127.100.d.1.Q',4,'Safety glasses must meet:','["The ANSI Z87 standard", "No standard", "Fashion standards", "Cost standards"]'::jsonb,0,'Z87 rates impact protection.','original'),
('127.100.d.2.A',3,'One job duty of a carpenter is to:','["Draw blood", "Build and repair structures made of wood", "Fly aircraft", "Prepare tax returns"]'::jsonb,1,'Carpenters frame and finish.','original'),
('127.100.d.2.A',4,'A cabinetmaker is a craft professional who:','["Pours foundations", "Lays roads", "Builds and installs cabinets", "Wires panels"]'::jsonb,2,'Cabinetmakers craft casework.','original'),
('127.100.d.2.B',3,'To research a career in carpentry, a student can check:','["Menus", "Weather maps", "Sports scores", "Training programs and apprenticeship requirements"]'::jsonb,3,'Programs describe how to enter.','original'),
('127.100.d.2.B',4,'Experience and job skills for a carpenter include:','["Reading plans, measuring accurately, and using tools safely", "Cooking", "Singing", "Painting portraits"]'::jsonb,0,'Core skills for the trade.','original'),
('127.100.d.3.A',3,'Which building material is used for framing walls in houses?','["Clay pots", "Dimensional lumber", "Foam peanuts", "Cotton"]'::jsonb,1,'Studs are dimensional lumber.','original'),
('127.100.d.3.A',4,'Plywood is used for sheathing because it comes in:','["Soft rolls", "Tiny pieces", "Large, strong, flat sheets", "Liquid form"]'::jsonb,2,'Panels cover large areas quickly.','original'),
('127.100.d.3.B',3,'Which is a hardwood?','["Fir", "Spruce", "Pine", "Oak"]'::jsonb,3,'Oak is a deciduous hardwood.','original'),
('127.100.d.3.B',4,'Pine and fir are softwoods commonly used for:','["Framing lumber", "Jewelry boxes only", "Piano keys only", "Violins only"]'::jsonb,0,'Softwoods are the standard for framing.','original'),
('127.100.d.3.C',3,'A lumber grade stamp indicates the board''s:','["Price", "Quality and species group", "Owner", "Delivery date"]'::jsonb,1,'Stamps tell grade and species.','original'),
('127.100.d.3.C',4,'Grade stamps on construction lumber usually show a moisture marking such as:','["XYZ", "ABC", "S-DRY or KD", "HOT"]'::jsonb,2,'Moisture content is marked.','original'),
('127.100.d.3.D',3,'Plywood sheets should be stored:','["Leaning in rain", "Loose in the open", "Standing in mud", "Flat and off the ground"]'::jsonb,3,'Flat storage prevents warping.','original'),
('127.100.d.3.D',4,'Handling long boards safely often takes:','["Two people or good lifting technique", "One hand", "A running start", "No planning"]'::jsonb,0,'Awkward loads are team lifts.','original'),
('127.100.d.3.E',3,'An I-joist is an example of:','["Plastic pipe", "Engineered lumber", "Glass", "Hardwood"]'::jsonb,1,'I-joists are engineered.','original'),
('127.100.d.3.E',4,'Glued laminated beams (glulam) are used when a design needs:','["Soft wood only", "Decoration only", "Long spans and high strength", "Cheap thin boards"]'::jsonb,2,'Glulams carry large loads.','original'),
('127.100.d.3.F',3,'A board foot of lumber equals:','["2 inches by 2 inches by 2 inches", "1 inch by 1 inch by 1 inch", "12 inches by 12 inches by 12 inches", "1 inch by 12 inches by 12 inches"]'::jsonb,3,'Standard definition.','original'),
('127.100.d.3.F',4,'How many board feet are in a 1 x 12 that is 10 feet long?','["10", "1", "12", "120"]'::jsonb,0,'(1 x 12 x 10) / 12 = 10.','original'),
('127.100.d.3.G',3,'Nails, screws, and bolts are examples of:','["Insulators", "Fasteners", "Finishes", "Conduits"]'::jsonb,1,'They join members.','original'),
('127.100.d.3.G',4,'A wedge anchor is used to fasten into:','["Glass", "Paper", "Concrete", "Drywall only"]'::jsonb,2,'Wedge anchors expand in concrete.','original'),
('127.100.d.4.A',3,'A tool used to cut wood by hand is a:','["Trowel", "Square", "Level", "Handsaw"]'::jsonb,3,'Saws cut.','original'),
('127.100.d.4.A',4,'A tool used to smooth a board''s surface by hand is a:','["Hand plane", "Mallet", "Plumb bob", "Chalk line"]'::jsonb,0,'Planes shave wood.','original'),
('127.100.d.4.B',3,'A carpenter should always cut:','["With eyes closed", "Away from the body", "Toward the body", "Toward a helper"]'::jsonb,1,'Cutting away avoids injury.','original'),
('127.100.d.4.B',4,'Dull hand tools are more dangerous because they:','["Last longer", "Cut easily", "Need more force and slip", "Stay cool"]'::jsonb,2,'Dull tools require force and slip.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
