from (values
('127.100.d.4.C',3,'Before using a portable power tool, a worker should check the:','["Color", "Time", "Phone", "Cord, guard, and switch"]'::jsonb,3,'Inspect before use.','original'),
('127.100.d.4.C',4,'A basic power tool rule is to keep:','["Guards in place and in working order", "Cords tangled", "Bits dull", "Guards off"]'::jsonb,0,'Guards prevent injury.','original'),
('127.100.d.4.D',3,'A portable tool used to drive screws quickly is the:','["Plane", "Cordless drill/driver", "Mallet", "Level"]'::jsonb,1,'Drivers sink screws.','original'),
('127.100.d.4.D',4,'A reciprocating saw is useful for:','["Sanding", "Measuring", "Rough cuts and demolition", "Fine joinery"]'::jsonb,2,'It cuts quickly.','original'),
('127.100.d.4.E',3,'When using a circular saw, the cord should be kept:','["Under the blade", "Wrapped around it", "In front of the blade", "Away from the blade"]'::jsonb,3,'Cord contact is a hazard.','original'),
('127.100.d.4.E',4,'A router bit should be installed with the tool:','["Unplugged", "Running", "Spinning", "Hot"]'::jsonb,0,'Disconnect power first.','original'),
('127.100.d.5.A',3,'A set of plans usually includes the floor plan, elevations, and:','["Maps of the moon", "Sections and details", "Recipes", "Menus"]'::jsonb,1,'Plans have multiple drawing types.','original'),
('127.100.d.5.A',4,'A drawing that shows a building''s side view is an:','["Site plan", "Section only", "Elevation", "Plan view"]'::jsonb,2,'Elevations show faces.','original'),
('127.100.d.5.B',3,'A solid heavy line on a plan usually represents:','["A hidden feature", "A dimension", "A center line", "A visible object edge"]'::jsonb,3,'Object lines are thick and solid.','original'),
('127.100.d.5.B',4,'Center lines are typically drawn as:','["Long and short dashes", "Dots only", "Solid thick lines", "Wavy lines"]'::jsonb,0,'Alternating dash pattern.','original'),
('127.100.d.5.C',3,'A symbol on a plan that looks like a quarter-circle swing shows a:','["Fireplace", "Door", "Window", "Stair"]'::jsonb,1,'Door swing is drawn as an arc.','original'),
('127.100.d.5.C',4,'Symbols for different materials in section views help the reader to:','["Count windows", "See hidden prices", "Identify what each part is made of", "Find colors"]'::jsonb,2,'Hatch patterns identify materials.','original'),
('127.100.d.5.D',3,'A circle with a line through it on an electrical plan may indicate a:','["Door", "Stair", "Window", "Light fixture or outlet"]'::jsonb,3,'Electric symbols are standardized.','original'),
('127.100.d.5.D',4,'A plumbing symbol labeled ''WC'' stands for:','["Water closet (toilet)", "Wall cavity", "Window casing", "Wood corner"]'::jsonb,0,'WC is a bathroom fixture.','original'),
('127.100.d.5.E',3,'''DR'' on a plan might mean:','["Dry", "Door", "Drive", "Drain only"]'::jsonb,1,'Check the legend.','original'),
('127.100.d.5.E',4,'''CLG'' on a plan stands for:','["Clamp", "Closet", "Ceiling", "Clearance"]'::jsonb,2,'CLG abbreviates ceiling.','original'),
('127.100.d.5.F',3,'Reading a plan scale of 1/4 inch = 1 foot, a 2-inch line represents:','["4 feet", "16 feet", "2 feet", "8 feet"]'::jsonb,3,'2 / 0.25 = 8.','original'),
('127.100.d.5.F',4,'A door schedule is used to find a door''s:','["Size and type", "Owner", "Price", "Weather"]'::jsonb,0,'Schedules list features.','original'),
('127.100.d.5.G',4,'If the plans and specifications conflict, the builder should:','["Pick one at random", "Ask the architect or engineer for clarification", "Hide the conflict", "Ignore both"]'::jsonb,1,'Conflicts need resolution.','original'),
('127.100.d.5.H',3,'A typical specification is divided into:','["Letters", "Chapters on cooking", "Divisions or sections by trade", "Random pages"]'::jsonb,2,'Specs are organized by division.','original'),
('127.100.d.5.H',4,'The ''general conditions'' part of a specification covers:','["Nail lengths", "Paint colors", "Wire sizes", "Administrative and contract requirements"]'::jsonb,3,'General conditions set the rules.','original'),
('127.100.d.5.I',3,'A quantity takeoff lists the:','["Materials required for a project", "Weather", "Phone numbers", "Sports teams"]'::jsonb,0,'Takeoffs count materials.','original'),
('127.100.d.5.I',4,'A takeoff for 120 linear feet of 2x4 plates in 8-foot pieces needs how many pieces?','["20", "15", "12", "10"]'::jsonb,1,'120 / 8 = 15.','original'),
('127.100.d.6.A',3,'The two main wood-frame systems are platform and:','["Concrete", "Timber-lock", "Balloon", "Pole barn only"]'::jsonb,2,'Balloon and platform framing are classic systems.','original'),
('127.100.d.6.A',4,'In platform framing, each floor''s walls sit on:','["The foundation only", "The footing", "The roof", "A subfloor platform"]'::jsonb,3,'Each level is built on the platform.','original'),
('127.100.d.6.B',3,'Floor system information such as joist size and spacing is found on:','["Framing plans and specifications", "Maps", "Furniture catalogs", "Menus"]'::jsonb,0,'Framing plans show members.','original'),
('127.100.d.6.B',4,'An engineered floor truss layout is usually provided by the:','["Local baker", "Truss manufacturer", "Paint company", "Shingle maker"]'::jsonb,1,'Manufacturers supply layouts.','original'),
('127.100.d.6.C',3,'The member that rests directly on the foundation wall is the:','["Rafter", "Header", "Sill plate", "Ridge"]'::jsonb,2,'Sill plates sit on foundation.','original'),
('127.100.d.6.C',4,'The band joist (rim joist) forms:','["The roof edge", "The window sill", "The stair rail", "The perimeter of the floor frame"]'::jsonb,3,'It encloses the joist ends.','original'),
('127.100.d.6.D',3,'Sill plates are anchored to the foundation using:','["Anchor bolts", "Rope", "Glue only", "Tape"]'::jsonb,0,'Bolts resist uplift.','original'),
('127.100.d.6.D',4,'A piece of sill sealer under the plate improves:','["Door fit", "Air and moisture protection", "Roof pitch", "Paint color"]'::jsonb,1,'Seals fill gaps.','original'),
('127.100.d.6.E',3,'Girder size is selected using load and:','["Window shape", "Nail color", "Span length", "Door weight"]'::jsonb,2,'Span tables use loads and spans.','original'),
('127.100.d.6.E',4,'A longer span or higher load requires a girder that is:','["Smaller", "Lighter", "Thinner", "Larger or stronger"]'::jsonb,3,'Bigger loads need bigger members.','original'),
('127.100.d.6.F',4,'Solid blocking is a type of:','["Bridging", "Trim", "Siding", "Flashing"]'::jsonb,0,'Blocking fills between joists.','original'),
('127.100.d.6.G',3,'Strip hardwood flooring is typically installed over:','["Bare dirt", "A subfloor", "Open joists", "Rafters"]'::jsonb,1,'Subfloors support finish floors.','original'),
('127.100.d.6.G',4,'Which flooring is usually glued, not nailed, to a concrete slab?','["Plank decking", "Hand-split planks", "Engineered wood or vinyl", "Strip oak nailed"]'::jsonb,2,'Concrete requires adhesive options.','original'),
('127.100.d.6.H',3,'Subflooring provides:','["A fence", "Air conditioning", "A roof", "A structural base for the finish floor"]'::jsonb,3,'Subfloor carries loads.','original'),
('127.100.d.6.H',4,'Underlayment is installed over the subfloor to:','["Create a smooth, even surface", "Provide insulation only", "Hold nails", "Add color"]'::jsonb,0,'Smooth surfaces help finish floors.','original'),
('127.100.d.6.I',4,'When joining floor framing members end to end, a carpenter selects fasteners based on:','["Weather forecast", "Member thickness and load", "Nail color", "Brand"]'::jsonb,1,'Fastener choice affects strength.','original'),
('127.100.d.6.J',3,'To estimate floor joists for a floor 24 feet long at 16 inches on center, count the spaces and add:','["Ten", "Zero", "One", "Fifty"]'::jsonb,2,'Spaces plus one equals joists.','original'),
('127.100.d.6.J',4,'A floor 24 feet long with joists at 16 inches on center needs about how many joists?','["18", "15", "24", "19"]'::jsonb,3,'288 / 16 = 18; plus 1 = 19.','original'),
('127.100.d.6.K',3,'The first step in constructing a floor assembly after the foundation is ready is to:','["Install the sill plate", "Hang drywall", "Lay the carpet", "Install the roof"]'::jsonb,0,'Sills go first.','original'),
('127.100.d.6.K',4,'When laying out joists, a carpenter marks their positions on the:','["Siding", "Sill and rim plates", "Windows", "Roof"]'::jsonb,1,'Layout starts on plates.','original'),
('127.100.d.6.L',3,'Cross bridging is installed:','["In the attic only", "On the roof", "Between joists in an X pattern", "On the sill"]'::jsonb,2,'Diagonal braces connect joists.','original'),
('127.100.d.6.L',4,'Bridging is often installed:','["At the very ends only", "Between studs", "On the roof", "At the mid-span of the joists"]'::jsonb,3,'Mid-span placement is effective.','original'),
('127.100.d.6.M',3,'A cantilever floor extends:','["Beyond the supporting wall", "Inside the wall", "Into the roof", "Below the footing"]'::jsonb,0,'A cantilever overhangs.','original'),
('127.100.d.6.M',4,'Joists in a cantilever must be properly:','["Cut short", "Supported and fastened", "Left loose", "Painted"]'::jsonb,1,'Overhangs carry bending forces.','original'),
('127.100.d.6.N',3,'Butt-joint plywood subfloor panels are installed with the long edge:','["Parallel to the joists", "Angled", "Perpendicular to the joists", "Vertical"]'::jsonb,2,'This pattern strengthens the floor.','original'),
('127.100.d.6.N',4,'Panel end joints in a subfloor should:','["Line up in a straight row", "Be left open", "Float in the air", "Fall over a joist and be staggered"]'::jsonb,3,'Support edges and stagger joints.','original'),
('127.100.d.6.O',3,'Tongue-and-groove panels are used to:','["Interlock edges and add stiffness", "Hold paint", "Hide nails", "Make noise"]'::jsonb,0,'T&G panels span between joists.','original'),
('127.100.d.6.O',4,'A common practice with T&G panels is to leave a small gap at the:','["Doors", "Panel ends or edges for expansion", "Roof", "Center of the room"]'::jsonb,1,'Gaps allow movement.','original'),
('127.100.d.7.A',3,'A wall layout shows the location of studs, plates, and:','["Furniture", "Paintings", "Openings such as doors and windows", "Rugs"]'::jsonb,2,'Layout marks all members.','original'),
('127.100.d.7.A',4,'A ceiling layout identifies the placement of:','["Faucets", "Floor tiles", "Door knobs", "Joists and blocking"]'::jsonb,3,'Ceiling joists are marked.','original'),
('127.100.d.7.B',3,'The top plate of a wall is usually:','["Doubled for strength", "Missing", "Tripled", "Plastic"]'::jsonb,0,'A double top plate ties walls together.','original'),
('127.100.d.7.B',4,'A rough opening for a window is framed with a header, sill, and:','["Sheathing only", "Trimmer and king studs", "Shims only", "Rafters"]'::jsonb,1,'Both trimmers and kings are used.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
