('127.100.d.10.K',3,'Weatherstrip, flashing, and sealant are used on windows and doors to:','["Keep out air and water", "Add noise", "Show color", "Add weight"]'::jsonb,0,'They seal openings.','original'),
('127.100.d.10.K',4,'Flashing tape applied around a window opening should be lapped so that water:','["Collects inside", "Sheds outward", "Is trapped", "Pools at the sill"]'::jsonb,1,'Shingle-style laps shed water.','original'),
('127.100.d.11.A',3,'A staircase that has no turn is a:','["L-shaped stair", "U-shaped stair", "Straight run stair", "Spiral stair"]'::jsonb,2,'Straight runs go in one direction.','original'),
('127.100.d.11.A',4,'A stair that makes a 180-degree turn with a landing is a:','["Straight stair", "Ladder", "Spiral stair", "U-shaped stair"]'::jsonb,3,'U stairs reverse direction.','original'),
('127.100.d.11.B',3,'The tread is the part of a step that you:','["Walk on", "Hold onto", "Climb under", "Look through"]'::jsonb,0,'Treads carry feet.','original'),
('127.100.d.11.B',4,'The stringer is the angled member that:','["Holds the rail only", "Supports the treads and risers", "Covers the wall", "Is a handrail"]'::jsonb,1,'Stringers carry the steps.','original'),
