('127.100.d.11.D',4,'The headroom on a stair plan must meet:','["Unlimited height", "Minimum code clearance", "No limit", "Paint rules"]'::jsonb,1,'Codes set headroom.','original'),
('127.100.d.11.E',3,'A total rise of 105 inches with 7-inch risers needs how many risers?','["7", "12", "15", "10"]'::jsonb,2,'105 / 7 = 15.','original'),
('127.100.d.11.E',4,'If a stair has 15 risers and 10-inch treads, the number of treads is usually:','["16", "15", "10", "14"]'::jsonb,3,'Treads are one fewer than risers.','original'),
